package com.opentv.app.data;
import com.opentv.app.model.Channel; import java.io.*; import java.util.*; import java.util.regex.*;
public final class M3uParser {private static final Pattern ATTR=Pattern.compile("([A-Za-z0-9_-]+)=\\\"([^\\\"]*)\\\"");private M3uParser(){}
public static List<Channel> parse(String text)throws IOException{List<Channel> out=new ArrayList<>();BufferedReader r=new BufferedReader(new StringReader(text==null?"":text));String line,info=null;while((line=r.readLine())!=null){line=line.trim();if(line.startsWith("#EXTINF:")){info=line;continue;}if(line.isEmpty()||line.startsWith("#")||info==null)continue;Map<String,String>a=new HashMap<>();Matcher m=ATTR.matcher(info);while(m.find())a.put(m.group(1).toLowerCase(),m.group(2));int comma=info.lastIndexOf(',');String name=comma>=0?info.substring(comma+1).trim():"Live channel";out.add(new Channel(first(a,"tvg-id","channel-id"),name,line,first(a,"tvg-logo","logo"),first(a,"group-title","category"),first(a,"tvg-country","country","tvg-country-code"),first(a,"tvg-language","language")));info=null;}return out;}
private static String first(Map<String,String>m,String...ks){for(String k:ks){String v=m.get(k);if(v!=null&&!v.trim().isEmpty())return v.trim();}return "";}}
